// src/components/ConfirmModal.js
import React from 'react';
import './ConfirmModal.css';

function ConfirmModal({ title, message, onConfirm, onCancel, type = 'warning' }) {
  return (
    <div className="confirm-modal-overlay">
      <div className="confirm-modal">
        <div className={`confirm-modal-icon ${type}`}>
          {type === 'warning' && <i className="fas fa-exclamation-triangle"></i>}
          {type === 'danger' && <i className="fas fa-times-circle"></i>}
          {type === 'info' && <i className="fas fa-info-circle"></i>}
          {type === 'success' && <i className="fas fa-check-circle"></i>}
        </div>
        <h3 className="confirm-modal-title">{title}</h3>
        <p className="confirm-modal-message">{message}</p>
        <div className="confirm-modal-buttons">
          <button className="btn-cancel" onClick={onCancel}>
            <i className="fas fa-times"></i> Cancelar
          </button>
          <button className={`btn-confirm ${type}`} onClick={onConfirm}>
            <i className="fas fa-check"></i> Aceptar
          </button>
        </div>
      </div>
    </div>
  );
}

export default ConfirmModal;
